// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { settleScroll } from "../../../main/frontend/graph-explorer/scroll-hold.ts";

// A list 300 px high showing content 1,000 px high. `drift` is how far the held element moved down on screen.
const VIEWPORT = 300;
const onScreen = (state, offset) => state.top + offset - state.scrollTop;

test("content that grew above the held element scrolls the list by as much", () => {
  const next = settleScroll({ top: 0, bottom: 0, scrollTop: 200 }, 1040, VIEWPORT, 40);
  assert.deepEqual(next, { top: 0, bottom: 0, scrollTop: 240 });
});

test("a list that got shorter than its scroll position keeps room below instead of scrolling back", () => {
  // Scrolled to the end (700), a filter closed: 200 px less content, and the browser clamped the scroll to 500.
  const next = settleScroll({ top: 0, bottom: 0, scrollTop: 500 }, 800, VIEWPORT, 200);
  assert.deepEqual(next, { top: 0, bottom: 200, scrollTop: 700 });
});

test("content that shrank above the held element near the top keeps room above", () => {
  const before = { top: 0, bottom: 0, scrollTop: 20 };
  const next = settleScroll(before, 950, VIEWPORT, -50);
  assert.deepEqual(next, { top: 30, bottom: 0, scrollTop: 0 });
  assert.equal(onScreen(next, 500 - 50), onScreen(before, 500), "the held element is back where it was");
});

test("room above is given back before the list scrolls when content above grows again", () => {
  const next = settleScroll({ top: 30, bottom: 0, scrollTop: 0 }, 1000, VIEWPORT, 50);
  assert.deepEqual(next, { top: 0, bottom: 0, scrollTop: 20 });
});

test("without a held element room goes once it is scrolled off screen, and nothing on screen moves", () => {
  // Room below: the user scrolled 120 px up from the end, so 80 px of the 200 px room is still on screen.
  const below = { top: 0, bottom: 200, scrollTop: 580 };
  assert.deepEqual(settleScroll(below, 800, VIEWPORT, 0), { top: 0, bottom: 80, scrollTop: 580 });
  // Room above: the user scrolled 20 px down into the list, so 10 px of the 30 px room is still on screen.
  const above = { top: 30, bottom: 0, scrollTop: 20 };
  const next = settleScroll(above, 1000, VIEWPORT, 0);
  assert.deepEqual(next, { top: 10, bottom: 0, scrollTop: 0 });
  assert.equal(onScreen(next, 400), onScreen(above, 400));
});

test("a short list that does not scroll still holds the element with room", () => {
  // 200 px of content in a 300 px list: the chips above appeared and pushed the list 52 px down.
  const next = settleScroll({ top: 0, bottom: 0, scrollTop: 0 }, 200, VIEWPORT, 52);
  assert.deepEqual(next, { top: 0, bottom: 152, scrollTop: 52 });
});
